import java.io.*;
import java.util.*;

public class CF819A_Variant2 {
    static int uniqueColors(int[] colors, int start, int end) {
        boolean[] seen = new boolean[24];
        int total = 0;
        for (int i = start; i <= end; i++) {
            int c = colors[i];
            if (!seen[c]) {
                seen[c] = true;
                total++;
            }
        }
        return total;
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int a = Integer.parseInt(st.nextToken());
        int b = Integer.parseInt(st.nextToken());
        int l = Integer.parseInt(st.nextToken()) - 1;
        int r = Integer.parseInt(st.nextToken()) - 1;
        int sumAB = a + b;
        int repeatCount = 4;
        int[] patternArr = new int[sumAB * repeatCount];
        int shiftH = l / sumAB;
        l -= shiftH * sumAB;
        r -= shiftH * sumAB;
        int segmentSize = (r - l + 1) / sumAB;
        if (segmentSize > 2) r -= (segmentSize - 2) * sumAB;
        int delta = Math.max(a - b, 1);
        for (int repIdx = 0; repIdx < repeatCount; repIdx++) {
            for (int k = 0; k < a - delta; k++)
                patternArr[sumAB * repIdx + k] = k;
            for (int k = 0; k < delta; k++)
                patternArr[sumAB * repIdx + a - delta + k] = (repIdx % 2 == 0) ? a - delta + k : a + k;
        }
        int minColors = a + a;
        for (int shiftAIdx = 1; shiftAIdx <= delta; shiftAIdx++) {
            for (int k = 0; k < b; k++)
                patternArr[0 + a + k] = patternArr[0 + a - shiftAIdx];
            for (int shiftBIdx1 = 1; shiftBIdx1 <= delta; shiftBIdx1++) {
                for (int k = 0; k < b; k++)
                    patternArr[sumAB + a + k] = patternArr[sumAB + a - shiftBIdx1];
                for (int shiftBIdx2 = 1; shiftBIdx2 <= delta; shiftBIdx2++) {
                    for (int k = 0; k < b; k++)
                        patternArr[2 * sumAB + a + k] = patternArr[2 * sumAB + a - shiftBIdx2];
                    for (int shiftBIdx3 = 1; shiftBIdx3 <= delta; shiftBIdx3++) {
                        for (int k = 0; k < b; k++)
                            patternArr[3 * sumAB + a + k] = patternArr[3 * sumAB + a - shiftBIdx3];
                        minColors = Math.min(minColors, uniqueColors(patternArr, l, r));
                    }
                }
            }
        }
        System.out.println(minColors);
    }
}
